@click.argument("provider")
@click.option("--connection", default="default", metavar="NAME", help="Connection name.")
@click.option(
    "--flow",
    type=click.Choice([e.value for e in FlowType], case_sensitive=False),
    metavar="FLOW",
    help=f"Authentication flow override ({', '.join(e.value for e in FlowType)}).",
)
@click.option("--scopes", metavar="SCOPES", help="Comma-separated list of permission scopes to request.")
@click.option("--base-url", metavar="URL", help="Override provider API base URL (e.g. for self-hosted enterprise).")
@click.option("--force", is_flag=True, help="Overwrite an existing connection if it already exists.")
@auth_command
async def login(
    ctx_obj: ContextObj,
    provider: str,
    connection: str,
    flow: str | None,
    scopes: str | None,
    base_url: str | None,
    force: bool,
) -> None:
    """Authenticate with PROVIDER using the configured flow."""
    actx = await ctx_obj.initialize()
    flow_value = FlowType(flow).value if flow else None
    scope_list = [s.strip() for s in scopes.split(",")] if scopes else None

    if force and not ctx_obj.quiet:
        ctx_obj.echo("Warning: Forcing login will overwrite any existing connection.", color="yellow")
    if not ctx_obj.json_output:
        ctx_obj.echo(f"Starting login for {provider}...", color="cyan")

    try:
        session_info = await actx.runtime_client.start_login(
            provider=provider,
            connection=connection,
            flow=flow_value,
            scopes=scope_list,
            base_url=base_url,
            force=force,
        )
        session_id = session_info["id"]
        status = session_info.get("status")
        login_result = {"status": "started", "record_status": status}

        if status == "completed":
            login_result["status"] = "success"
        else:
            next_action = session_info.get("next_action", {"type": "none"})
            action_type = next_action.get("type")

"""CLI Context management and decorators."""

import functools
import json as json_lib
import os
from pathlib import Path
from typing import Any

import click

from authsome.cli.client import AuthsomeApiClient
from authsome.cli.daemon_control import resolve_runtime_client
from authsome.proxy.runner import ProxyRunner


class CliRuntime:
    """CLI-local wiring around the daemon API client."""

    def __init__(self, client: AuthsomeApiClient) -> None:
        self.runtime_client = client
        self.home = Path(os.environ.get("AUTHSOME_HOME", str(Path.home() / ".authsome")))

    async def doctor(self) -> dict[str, Any]:
        return await self.runtime_client.doctor()

    def require_local_proxy(self) -> ProxyRunner:
        return ProxyRunner(client=self.runtime_client, home=self.home)


class ContextObj:
    """Context object passed to all commands."""

    def __init__(self, json_output: bool, quiet: bool, no_color: bool):
        self.json_output = json_output
        self.quiet = quiet
        self.no_color = no_color
        self._ctx: CliRuntime | None = None

    async def initialize(self) -> CliRuntime:
        if self._ctx is None:
            self._ctx = CliRuntime(await resolve_runtime_client())
        return self._ctx

    def print_json(self, data: Any) -> None:
        output = {"v": 1}
        if isinstance(data, dict):
            output.update(data)
        else:
            output["data"] = data
        click.echo(json_lib.dumps(output, indent=2))

    def echo(self, message: str, err: bool = False, color: str | None = None, nl: bool = True) -> None:
        if self.quiet:
            return
        if self.no_color:
            color = None
        click.secho(message, err=err, fg=color, nl=nl)


pass_ctx = click.make_pass_decorator(ContextObj)


def common_options(f):
    @click.option("--json", "json_output", is_flag=True, help="Output in machine-readable JSON format.")
    @click.option("--quiet", is_flag=True, help="Suppress non-essential output.")
    @click.option("--no-color", is_flag=True, help="Disable ANSI colors.")
    @functools.wraps(f)
    def wrapper(*args, **kwargs):
        json_output = kwargs.pop("json_output", False)
        quiet = kwargs.pop("quiet", False)
        no_color = kwargs.pop("no_color", False)
        ctx = click.get_current_context()
        if getattr(ctx, "obj", None) is None:
            ctx.obj = ContextObj(json_output, quiet, no_color)
        else:
            if json_output:
                ctx.obj.json_output = True
            if quiet:
                ctx.obj.quiet = True
            if no_color:
                ctx.obj.no_color = True
